// POST /api/forget-device  { device, apagar_gravacoes }
const b = msg.payload || {};
const h = String((msg.req.headers || {}).authorization || '');
const sessao = h.replace(/^Bearer\s+/i, '').trim();
const device = String(b.device || '');
if (!sessao || !/^[A-Za-z0-9-]{3,32}$/.test(device)) {
    msg.statusCode = 400;
    msg.payload = { error: 'missing' };
    return [null, msg];
}
// Padrao e apagar: a gravacao antiga ficaria visivel para o proximo dono.
msg.apagar = b.apagar_gravacoes !== false;
msg.device = device;
msg.params = [sessao, device];
return [msg, null];

const st = ((msg.payload && msg.payload[0]) || {}).status;
if (st === 'ok') {
    // A box ja foi solta no banco; agora a ordem para ela voltar ao pareamento.
    // Mensagem nova para o MQTT: a original carrega req/res da requisicao HTTP.
    const ordem = {
        topic: 'devices/' + msg.device + '/sistema/command',
        payload: JSON.stringify({ action: 'esquecer', apagar_gravacoes: msg.apagar }),
        qos: 1,
        retain: false,
    };
    msg.statusCode = 200;
    msg.payload = { status: 'esquecida' };
    return [ordem, msg];
}
if (st === 'offline') {
    msg.statusCode = 409;
    msg.payload = { error: 'offline' };
    return [null, msg];
}
msg.statusCode = 403;
msg.payload = { error: 'forbidden' };
return [null, msg];
